import sys
import math

MOD = 998244353
factorials = []
inverseFactorials = []

def setup():
    global factorials, inverseFactorials
    size = 10**6
    factorials = [1] * size
    inverseFactorials = [1] * size
    for i in range(1, size):
        factorials[i] = (factorials[i-1] * i) % MOD
    inverseFactorials[-1] = pow(factorials[-1], MOD - 2, MOD)
    for i in range(size - 2, -1, -1):
        inverseFactorials[i] = (inverseFactorials[i + 1] * (i + 1)) % MOD

def calculateCombination(n, k):
    if k > n or k < 0:
        return 0
    return (factorials[n] * (inverseFactorials[k] * inverseFactorials[n - k] % MOD)) % MOD

def add(a, b):
    return (a + b) % MOD

def sub(a, b):
    return ((a - b) % MOD + MOD) % MOD

def mul(a, b):
    return (a * b) % MOD

def fastPow(base, exp):
    return pow(base, exp, MOD)

def computePower(base, exp):
    total = 0
    for i in range(base):
        term = (fastPow(base - i, exp) * calculateCombination(base, i)) % MOD
        if i % 2 == 0:
            total = add(total, term)
        else:
            total = sub(total, term)
    return total

def main():
    setup()
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k == 0:
        print(factorials[n])
        return
    if k >= n:
        print(0)
        return
    remaining = n - k
    assignWays = computePower(remaining, n)
    pickWays = calculateCombination(n, remaining)
    total = mul(assignWays, pickWays)
    print(mul(total, 2))

if __name__ == "__main__":
    try:
        main()
    except:
        print(0)

